import {validateEnquiry} from './contact-contract.mjs';
const form=document.getElementById('contact-form');
if(form){
  const status=form.querySelector('.form-message'),send=form.querySelector('button[type="submit"]');
  function message(text,state){status.textContent=text;status.dataset.state=state;}
  function validate(){const result=validateEnquiry(Object.fromEntries(new FormData(form)));for(const field of ['name','business','email','phone','topic','message']){const input=form.elements.namedItem(field),error=document.getElementById(field+'-error');input.setAttribute('aria-invalid',String(!!result.errors[field]));error.textContent=result.errors[field]||'';}if(!result.valid){message('Please review the highlighted fields. Nothing has been sent.','error');const first=Object.keys(result.errors).find(k=>k!=='website');if(first)form.elements.namedItem(first).focus();}return result;}
  document.getElementById('check-enquiry')?.addEventListener('click',()=>{if(validate().valid)message('Your enquiry is ready. Online sending is not enabled; nothing has been sent or stored.','ready');});
  form.addEventListener('submit',async event=>{event.preventDefault();const result=validate();if(!result.valid)return;if(form.dataset.enabled!=='true'){message('Online enquiries are unavailable. Nothing has been sent or stored.','unavailable');return;}if(send.disabled)return;send.disabled=true;form.setAttribute('aria-busy','true');message('Submitting your enquiry…','pending');try{const response=await fetch(form.dataset.endpoint,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(result.clean),credentials:'same-origin',signal:AbortSignal.timeout(15000)});const payload=await response.json();if(!response.ok||payload.accepted!==true)throw Error('not accepted');message('Your enquiry was accepted. Email delivery may still be pending.','success');form.reset();}catch{message('We could not confirm that your enquiry was accepted. Please try again later. Your form details have been kept on this page.','error');}finally{send.disabled=false;form.removeAttribute('aria-busy');}});
}
